-- preflight - aborts if the DB is not in the expected state
-- generated by scripts/prod-open/sat-expand-sql.ts. Run: npx supabase db query --linked -f <this file>. Idempotent; no deletes/overwrites; nothing is published here (drafts only).

do $pf$
begin
  if (select count(*) from mock_exam_sets where status = 'published' and archived_at is null and name ~ '^SAT Practice Test ([1-9]|1[0-3])$') <> 13 then raise exception 'expected 13 published SAT sets (Test 1-13)'; end if;
  if not exists (select 1 from profiles where role = 'admin') then raise exception 'no admin profile'; end if;
  if not exists (select 1 from subjects where name = 'SAT Reading & Writing' and archived_at is null) or not exists (select 1 from subjects where name = 'SAT Math' and archived_at is null) then raise exception 'SAT subjects missing'; end if;
  raise notice 'preflight ok: published sets=%, already-imported gids=%, existing non-archived Test 14-26 sets=%', 13,
    (select count(*) from problem_versions where quality->'mockExamGeneration'->>'gid' ~ '^(sx|sy|sz|e1018)-'),
    (select count(*) from mock_exam_sets where name ~ '^SAT Practice Test (1[4-9]|2[0-6])$' and archived_at is null and status <> 'archived');
end
$pf$;
select current_database() as db, (select count(*) from problems) as problems, (select count(*) from mock_exam_sets) as sets;
